@RestController
public class TermDepositController {

	private static final Logger log = LoggerFactory.getLogger(TermDepositController.class);
	
	private TermDepositService termDepositService;
	
	@Autowired
	public TermDepositController(TermDepositService termDepositService) {
		this.termDepositService = termDepositService;
	}
	
	@RequestMapping(value = "/term-deposit", method = RequestMethod.GET, produces = MediaType.APPLICATION_JSON_VALUE)
	public ResponseEntity<ServiceResponse<TermDepositResponse>> termDeposit(@RequestParam(required = true) String correlationId, @RequestParam(name = "wait", defaultValue = "3000", required = false) Integer wait) throws CustomInternalServerError, CustomBadRequestException, CustomCore02MQResponseException {
		log.info("Core02-API GET term-deposit called.");
		ServiceResponse<TermDepositResponse> response = termDepositService.termDeposit(correlationId, wait);
		log.info("Core02-API GET term-deposit reposponse: {}", response.toString());
		return new ResponseEntity<ServiceResponse<TermDepositResponse>>(response, HttpStatus.valueOf(response.getCode()));
		
	}
	
	@ApiResponses(value = {
			@ApiResponse(code = 204, message = "No Content", response = ExceptionResponse.class),
			@ApiResponse(code = 400, message = "Bad Request", response = ExceptionResponse.class),
			@ApiResponse(code = 500, message = "Internal server error", response = ExceptionResponse.class)
	})
	@RequestMapping(value = "/term-deposit", method = RequestMethod.POST, produces = MediaType.APPLICATION_JSON_VALUE)
	public ResponseEntity<ServiceResponse<TermDepositResponse>> termDeposit(@RequestParam(name = "mode", required = true) ModeTypeTermDeposit modeType, @RequestParam(name = "function", required = true) FunctionTypeTermDeposit functionType, @RequestParam(required = false) String source, @RequestParam(name = "wait", required = false, defaultValue = "0") int wait, @RequestBody(required = true) TermDepositRequest request) throws CustomCore02MQResponseException, CustomBadRequestException, CustomInternalServerError {
		log.info("****************************************************************************************");
		log.info("Core02-API POST term-deposit called with params wait '" + wait + "', mode '" + modeType + "', function '" + functionType + "', source '" + source + "', body '" + request + "'.");
		ServiceResponse<TermDepositResponse> response = termDepositService.termDeposit(modeType.getCode(), functionType.getCode(), source, wait, request);
		log.info("Core02-API POST term-deposit reposponse: {}", response.toString());
		log.info("****************************************************************************************");
		return new ResponseEntity<ServiceResponse<TermDepositResponse>>(response, HttpStatus.valueOf(response.getCode()));
	}
}

