@Service
public class TermDepositService {

	private static final Logger log = LoggerFactory.getLogger(TermDepositService.class);
	
	private ProjectConfig config;
	private MQService mqService;
	
	@Autowired
	public TermDepositService(ProjectConfig config, MQService mqService) {
		this.config = config;
		this.mqService = mqService;
	}
	
	public ServiceResponse<TermDepositResponse> termDeposit(String correlationId, Integer wait) throws CustomInternalServerError, CustomBadRequestException, CustomCore02MQResponseException {
		String queue = config.getQueue().get("term-deposit");
		
		try {
			log.info("Request GET for MQConsumer queue: " + queue + "correlitionId: "+ correlationId + "wait: " + wait  );
			String xml = mqService.mqConsumer(queue, correlationId, wait);
			TermDepositResponse termDepositResponse = XMLUtility.convertXMLToTermDepositResponse(xml);
			log.info("Success Core02-mq consume with correlation ID '" + correlationId + "'" + "and response XML: " + xml);
			log.info("Deal Number from xml: " + termDepositResponse.getDealNumber());
			return new ServiceResponse<TermDepositResponse>(200, "OK", termDepositResponse);
		} catch (JAXBException e) {
			log.error("Convert XML to Term deposit response exception: " + e.getMessage());
			throw new CustomInternalServerError("Convert XML to Term deposit response exception: " + e.getMessage());
		}
	}

	public ServiceResponse<TermDepositResponse> termDeposit(String mode, String function, String source, int wait, TermDepositRequest request) throws CustomCore02MQResponseException, CustomBadRequestException, CustomInternalServerError {		
		String queue = config.getQueue().get("term-deposit");
		String driver = config.getDriver().get("term-deposit");
		String application = config.getApplication().get("term-deposit");
		
		String body = null;
		try {
			body = XMLUtility.convertTermDepositRequestToXML(application, mode, function, source, request);
			log.info("1.1 XML REQUEST: " + body);
		} catch (JsonProcessingException e) {
			log.error("Term Deposit JsonProcessingException: " + e);
			return new ServiceResponse<>(400, e.getMessage());
		}
		
		// Produce Core02-MQ
		ServiceResponse<MQResponse> mqProducer = mqService.mqProducer(queue, driver, application, body);
		log.info("1.2 Response from MQSERVICE for PRODUCER: " + mqProducer.toString());
	
		String correlationId = mqProducer.getContent().getCorrelationId();
		if (correlationId != null && !correlationId.isEmpty()) {
			if (wait == 0) {
				log.info("2.0 WARNING wait is 0 for correlation ID" + correlationId);
				log.info("Success asynchronous account opened with queue '" + queue + "', driver '" + driver + "', application '" + application + "' and body '" + body + "'");
				return new ServiceResponse<TermDepositResponse>(200, "OK", new TermDepositResponse(correlationId));
			} else {
				String xml = null;
				
				try {
					log.info("2.1 Request for POST MQConsumer queue: " + queue + "correlitionId: "+ correlationId + "wait: " + wait  );
					xml = mqService.mqConsumer(queue, correlationId, wait);
					log.info("2.2 XML Response from MQConsumer (String type): " + xml);
					TermDepositResponse termDepositResponse = XMLUtility.convertXMLToTermDepositResponse(xml);
					log.info("2.3 Converted XML from String (from MQConsumer): " + termDepositResponse.toString());
					log.info("Success synchronous account opened with queue '" + queue + "', driver '" + driver + "', application '" + application + "' and body '" + body + "'");
					termDepositResponse.setCorrelationId(correlationId); // imijajlovic SR248852 (missing TDN problem)
					return new ServiceResponse<TermDepositResponse>(200, "OK", termDepositResponse);
				} catch (JAXBException e) {
					log.error("Convert XML to Term deposit response exception: " + e.getMessage());
					throw new CustomInternalServerError("Convert XML to Term deposit response exception: " + e.getMessage());
				}
			}
		} else {
			log.error("Open account Core02-MQ producer error.");
			return new ServiceResponse<>(400, "Core02-MQ producer error.");
		}
