				request.getContextPath());
		
		return new ResponseEntity<ExceptionResponse>(response, HttpStatus.BAD_REQUEST);
	}
	
	@SuppressWarnings("rawtypes")
	@ExceptionHandler(CustomInternalServerError.class)
	public final ResponseEntity handleInternalServerError(CustomInternalServerError ex, WebRequest request) {
		ExceptionResponse response = new ExceptionResponse(
				HttpStatus.INTERNAL_SERVER_ERROR.value(),
				ex.getMessage(),
				request.getContextPath());
		
		return new ResponseEntity<ExceptionResponse>(response, HttpStatus.INTERNAL_SERVER_ERROR);
	}
	
	@SuppressWarnings("rawtypes")
	@ExceptionHandler(CustomCore02MQResponseException.class)
	public final ResponseEntity handleCore02MQResponseException(CustomCore02MQResponseException ex, WebRequest request) {
		ExceptionResponse response = new ExceptionResponse(
				HttpStatus.INTERNAL_SERVER_ERROR.value(),
				ex.getMessage(),
				request.getContextPath());
		
		return new ResponseEntity<ExceptionResponse>(response, HttpStatus.INTERNAL_SERVER_ERROR);
	}
	
	@SuppressWarnings("rawtypes")
	@ExceptionHandler(MethodArgumentTypeMismatchException.class)
	public final ResponseEntity handleTypeMismatchException(MethodArgumentTypeMismatchException ex, WebRequest request) {
	    String name = ex.getName();
	    String type = ex.getRequiredType().getSimpleName();
	    Object value = ex.getValue();
	    String message = String.format("Parameter '%s' should be a valid '%s' and '%s' isn't.", name, type, value);

	    ExceptionResponse response = new ExceptionResponse(
				HttpStatus.BAD_REQUEST.value(),
				message,
				request.getContextPath());
		
		return new ResponseEntity<ExceptionResponse>(response, HttpStatus.BAD_REQUEST);
	}

	@SuppressWarnings("rawtypes")
	@ExceptionHandler(Exception.class)
	public final ResponseEntity handleAllException(Exception ex, WebRequest request) {
		ExceptionResponse response = new ExceptionResponse(500, ex.getMessage(), request.getContextPath());
		
		return new ResponseEntity<ExceptionResponse>(response, HttpStatus.INTERNAL_SERVER_ERROR);
	}

}

