package rs.unicredit.core02api.service;

import javax.xml.bind.JAXBException;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;

import com.fasterxml.jackson.core.JsonProcessingException;

import rs.unicredit.core02api.configuration.Db2ConfigProperties;
import rs.unicredit.core02api.configuration.ProjectConfig;
import rs.unicredit.core02api.exception.CustomBadRequestException;
import rs.unicredit.core02api.exception.CustomCore02MQResponseException;
import rs.unicredit.core02api.exception.CustomInternalServerError;
import rs.unicredit.core02api.utility.XMLUtility;
import rs.unicredit.core02api.vo.MQResponse;
import rs.unicredit.core02api.vo.ServiceResponse;
import rs.unicredit.core02api.vo.TermDepositRequest;
import rs.unicredit.core02api.vo.TermDepositResponse;

@Service
public class TermDepositService {

	private static final Logger log = LoggerFactory.getLogger(TermDepositService.class);
	
	private ProjectConfig config;
	private MQService mqService;
	private NamedParameterJdbcTemplate db2NamedParameterJdbcTemplate;
	private Db2ConfigProperties db2ConfigProperties;
	
	@Autowired
	public TermDepositService(ProjectConfig config, MQService mqService, @Qualifier("db2NamedParameterJdbcTemplate") NamedParameterJdbcTemplate db2NamedParameterJdbcTemplate, Db2ConfigProperties db2ConfigProperties) {
		this.config = config;
		this.mqService = mqService;
		this.db2NamedParameterJdbcTemplate = db2NamedParameterJdbcTemplate;
		this.db2ConfigProperties = db2ConfigProperties;
	}
	
	public ServiceResponse<TermDepositResponse> termDeposit(String correlationId, Integer wait) throws CustomInternalServerError, CustomBadRequestException, CustomCore02MQResponseException {
		String queue = config.getQueue().get("term-deposit");
		
		try {
			log.info("Request GET for MQConsumer queue: " + queue + "correlitionId: "+ correlationId + "wait: " + wait  );
			String xml = mqService.mqConsumer(queue, correlationId, wait);
			TermDepositResponse termDepositResponse = XMLUtility.convertXMLToTermDepositResponse(xml);
			log.info("Success Core02-mq consume with correlation ID '" + correlationId + "'" + "and response XML: " + xml);
			log.info("Deal Number from xml: " + termDepositResponse.getDealNumber());
			return new ServiceResponse<TermDepositResponse>(200, "OK", termDepositResponse);
		} catch (JAXBException e) {
			log.error("Convert XML to Term deposit response exception: " + e.getMessage());
			throw new CustomInternalServerError("Convert XML to Term deposit response exception: " + e.getMessage());
		}
	}

	public ServiceResponse<TermDepositResponse> checkDeposit(String coreId, String contractNumber) throws CustomBadRequestException, CustomInternalServerError {
		if (coreId == null || coreId.trim().isEmpty()) {
			throw new CustomBadRequestException("Parameter 'coreId' is required.");
		}
		if (contractNumber == null || contractNumber.trim().isEmpty()) {
			throw new CustomBadRequestException("Parameter 'contractNumber' is required.");
		}

		String resolvedQuery = db2ConfigProperties.getCheckDepositQuery().replace("{daySchema}", db2ConfigProperties.getDaySchema());
		MapSqlParameterSource parameters = new MapSqlParameterSource()
				.addValue("p_core_id", coreId.trim())
				.addValue("p_ugovor", contractNumber.trim());

		try {
			log.info("Core02-API check-deposit called for coreId '{}' and contractNumber '{}'.", coreId, contractNumber);
			return db2NamedParameterJdbcTemplate.query(resolvedQuery, parameters, rs -> {
				if (!rs.next()) {
					return new ServiceResponse<TermDepositResponse>(204, "No deposit found for provided coreId and contractNumber.");
				}

				TermDepositResponse response = new TermDepositResponse();
				response.setDealNumber(rs.getString("b60tdn"));
				response.setMessage("Deposit found.");
				response.setSuccess("Y");

				return new ServiceResponse<TermDepositResponse>(200, "OK", response);
			});
		} catch (DataAccessException ex) {
			log.error("DB2 check-deposit query failed for coreId '{}' and contractNumber '{}': {}", coreId, contractNumber, ex.getMessage());
			throw new CustomInternalServerError("DB2 check-deposit query failed: " + ex.getMostSpecificCause().getMessage());
		}
	}

	public ServiceResponse<TermDepositResponse> termDeposit(String mode, String function, String source, int wait, TermDepositRequest request) throws CustomCore02MQResponseException, CustomBadRequestException, CustomInternalServerError {		
		String queue = config.getQueue().get("term-deposit");
		String driver = config.getDriver().get("term-deposit");
		String application = config.getApplication().get("term-deposit");
		
		String body = null;
		try {
			body = XMLUtility.convertTermDepositRequestToXML(application, mode, function, source, request);
			log.info("1.1 XML REQUEST: " + body);
		} catch (JsonProcessingException e) {
			log.error("Term Deposit JsonProcessingException: " + e);
			return new ServiceResponse<>(400, e.getMessage());
		}
		
		// Produce Core02-MQ
		ServiceResponse<MQResponse> mqProducer = mqService.mqProducer(queue, driver, application, body);
		log.info("1.2 Response from MQSERVICE for PRODUCER: " + mqProducer.toString());
	
		String correlationId = mqProducer.getContent().getCorrelationId();
		if (correlationId != null && !correlationId.isEmpty()) {
			if (wait == 0) {
				log.info("2.0 WARNING wait is 0 for correlation ID" + correlationId);
